meta.script:
[
    'CookiebotOnConsentReady',
    'CookiebotOnLoad',
    'CookiebotOnAccept',
    'CookiebotOnDecline',
    'CookiebotOnDialogInit',
    'CookiebotOnDialogDisplay',
    'CookiebotOnTagsExecuted'
].forEach(function (eventName) {
    window.addEventListener(eventName, function () {
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
            event: "track_event",
            event_name: eventName,
            event_attributes: {
                event_type: "system",
                custom_timestamp: Date.now(),
                context: "cookie banner"
            },
        });
    });
});

window.addEventListener("click", function (event) {
    let button;
    if (event.target.tagName.toUpperCase() === "BUTTON") {
        button = event.target;
    } else if (event.target.parentElement?.tagName.toUpperCase() === "BUTTON") {
        button = event.target.parentElement;
    } else {
        return;
    }

    if ([
        'CybotCookiebotDialogBodyLevelButtonCustomize',
        'CybotCookiebotDialogBodyLevelButtonLevelOptinAllowAll',
        'CybotCookiebotDialogBodyLevelButtonLevelOptinAllowallSelection',
        'CybotCookiebotDialogBodyButtonDecline'
    ].includes(button.getAttribute('id'))) {
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
            event: "track_event",
            event_name: "internal_click",
            event_attributes: {
                event_type: "user",
                custom_timestamp: Date.now(),
                context: "cookie banner",
                element_id: button.getAttribute('id'),
                text_content: button.textContent
            },
        });
        window.dataLayer.push({event_attributes: null});
    }
});

document.addEventListener('DOMContentLoaded', () => {
    window.dataLayer = window.dataLayer || [];

    window.dataLayer.push({
        app_name: 'elements blog',
        app_env: "production",
        page_type: 'blog',
        ga_param: new URLSearchParams(location.search).get('_ga') ?? undefined,
        page_location: window.location.href,
        page_title: document.title,
        page_referrer: document.referrer,
        article_id: 94758,
        article_name: "Why we're retiring Reshot and what's next for Envato's core creative platform",
        article_author: "julia",
        date_published: "2026-01-20T17:49:02+11:00",
        date_updated: "2026-05-19T17:18:17+10:00",
        category_path_json: "[[\"news\",\"product-updates\"]]",
        user_attributes: {envato_client_id: window.ENVATO_CLIENT_ID},
    });

    window.dataLayer.push({
        event: 'analytics_ready',
        event_attributes: {
            custom_timestamp: Date.now(),
            event_type: 'user',
        }
    });
});

section.script:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [{"@type":"Question","name":"When will Reshot officially shut down?","acceptedAnswer":{"@type":"Answer","text":"Reshot will be retired in January 2026. After that date, assets will no longer be available for download."}},{"@type":"Question","name":"Can I still use assets I\u2019ve already downloaded?","acceptedAnswer":{"@type":"Answer","text":"Yes. Anything you downloaded before the shutdown remains covered under Reshot\u2019s original free commercial license."}},{"@type":"Question","name":"What\u2019s the difference between Reshot and Envato?","acceptedAnswer":{"@type":"Answer","text":"Reshot focused on free icons and illustrations. Envato offers AI tools, along with a broader, unlimited library of creative assets (fonts, templates, photos, videos, music, and more), all with simple commercial licensing."}}]}

